/**
 * Thin wrapper around window.tableau.extensions.initializeAsync().
 * Resolves immediately when Tableau runtime is absent (dev/test environment).
 */

type TableauExtensions = {
  extensions: {
    initializeAsync: () => Promise<void>;
  };
};

declare global {
  interface Window {
    tableau?: TableauExtensions;
  }
}

let initialized = false;

/**
 * Returns the Tableau user identifier from the extension context.
 * Falls back to "dev-user" when no Tableau runtime is present (dev/test).
 * Must be called AFTER initializeExtension() resolves.
 */
export function getTableauUserId(): string {
  if (typeof window === 'undefined' || !window.tableau) {
    return 'dev-user';
  }
  try {
    // tableau.extensions.environment.context is available post-initializeAsync()
    const context = (window.tableau.extensions as unknown as {
      environment?: { context?: { user?: { name?: string } } };
    }).environment?.context;
    return context?.user?.name ?? 'unknown-user';
  } catch {
    return 'unknown-user';
  }
}

export async function initializeExtension(): Promise<void> {
  if (typeof window === 'undefined' || !window.tableau) {
    // No Tableau runtime — running in dev/test outside Tableau Desktop/Cloud.
    // Resolve immediately so the extension shell renders normally.
    return;
  }
  if (initialized) return;
  initialized = true;
  await window.tableau.extensions.initializeAsync();
}
/**
 * Backend HTTP client. All fetch calls go through apiFetch.
 * Errors always surface as ApiError — never raw fetch rejections or non-2xx responses.
 * JSON fields from the API are snake_case; camelCase conversion happens at the call site.
 */

const BACKEND_URL = (import.meta.env.VITE_BACKEND_URL as string | undefined) || 'http://localhost:8000';
const FETCH_TIMEOUT_MS = 10_000;

export class ApiError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

  let response: Response;
  try {
    response = await fetch(`${BACKEND_URL}${path}`, {
      ...init,
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        ...init?.headers,
      },
    });
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      throw new ApiError('REQUEST_TIMEOUT', 'Request timed out', 0);
    }
    throw new ApiError('NETWORK_ERROR', 'Unable to reach the autom9 backend', 0);
  } finally {
    clearTimeout(timeoutId);
  }

  if (!response.ok) {
    let code = 'UNKNOWN_ERROR';
    let message = `Request failed with status ${response.status}`;
    try {
      const body = (await response.json()) as { error?: { code?: string; message?: string } };
      code = body?.error?.code ?? code;
      message = body?.error?.message ?? message;
    } catch {
      // non-JSON error body — keep defaults
    }
    throw new ApiError(code, message, response.status);
  }

  try {
    return (await response.json()) as T;
  } catch {
    throw new ApiError('INVALID_RESPONSE', 'Server returned a non-JSON response', response.status);
  }
}
/**
 * Session store — holds session_id for the current extension session.
 * Created on extension load via POST /api/sessions.
 * Resets on every extension load (never persisted to localStorage).
 */
class SessionStore {
  sessionId = $state<string | null>(null);
  tableauUserId = $state<string | null>(null);
}

export const sessionStore = new SessionStore();
/**
 * Status store — holds integration health check results.
 * Populated once on extension load from GET /api/status.
 * Resets on every extension load.
 */

export interface IntegrationStatus {
  name: string;
  status: 'healthy' | 'unavailable';
  latency_ms: number | null;
  error: string | null;
}

class StatusStore {
  integrations = $state<IntegrationStatus[]>([]);
  loading = $state(false);
  error = $state<string | null>(null);
}

export const statusStore = new StatusStore();
<script lang="ts">
  import { statusStore } from '../stores/status.svelte';

  const DISPLAY_NAMES: Record<string, string> = {
    smartsheet: 'Smartsheet',
    google_calendar: 'Google Calendar',
    google_docs: 'Google Docs',
    tableau_data: 'Tableau Data',
  };
</script>

<div class="status-bar">
  {#if statusStore.loading}
    <p class="status-checking">Checking integrations…</p>
  {:else if statusStore.error}
    <p class="status-bar-error">Status check failed: {statusStore.error}</p>
  {:else}
    <ul class="status-list">
      {#each statusStore.integrations as integration (integration.name)}
        <li class="status-item status-{integration.status}">
          <span class="status-indicator" aria-hidden="true">
            {integration.status === 'healthy' ? '●' : '○'}
          </span>
          <span class="status-name">
            {DISPLAY_NAMES[integration.name] ?? integration.name}
          </span>
          {#if integration.status === 'unavailable' && integration.error}
            <span class="status-error-msg">— {integration.error}</span>
          {/if}
        </li>
      {/each}
    </ul>
  {/if}
</div>

<style>
  .status-bar {
    font-family: sans-serif;
    font-size: 0.85rem;
    padding: 0.5rem 1rem;
    border-bottom: 1px solid #e0e0e0;
  }
  .status-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .status-item {
    display: flex;
    align-items: center;
    gap: 0.25rem;
  }
  .status-healthy .status-indicator {
    color: #2e7d32;
  }
  .status-unavailable .status-indicator {
    color: #c62828;
  }
  .status-error-msg {
    color: #888;
    font-size: 0.8rem;
  }
  .status-checking,
  .status-bar-error {
    margin: 0;
    color: #555;
  }
  .status-bar-error {
    color: #c62828;
  }
</style>
<script lang="ts">
  import { onMount } from 'svelte';
  import { initializeExtension, getTableauUserId } from './lib/tableau';
  import { apiFetch, ApiError } from './lib/api';
  import { sessionStore } from './stores/session.svelte';
  import { statusStore } from './stores/status.svelte';
  import StatusBar from './components/StatusBar.svelte';

  type AppStatus = 'loading' | 'ready' | 'error';

  let appStatus = $state<AppStatus>('loading');
  let errorMessage = $state('');

  onMount(async () => {
    try {
      // Step 1: Initialize Tableau runtime
      await initializeExtension();

      // Step 2: Get Tableau user identity
      const tableauUserId = getTableauUserId();
      sessionStore.tableauUserId = tableauUserId;

      // Step 3: Create backend session
      const sessionResponse = await apiFetch<{
        data: { session_id: string; started_at: string };
      }>('/api/sessions', {
        method: 'POST',
        body: JSON.stringify({ tableau_user_id: tableauUserId }),
      });
      sessionStore.sessionId = sessionResponse.data.session_id;

      // Step 4: Fetch integration statuses
      statusStore.loading = true;
      const statusResponse = await apiFetch<{
        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
      }>('/api/status', {
        headers: { 'X-Autom9-Session': sessionStore.sessionId },
      });

      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
        name: i.name,
        status: i.status as 'healthy' | 'unavailable',
        latency_ms: i.latency_ms,
        error: i.error,
      }));
      statusStore.loading = false;

      appStatus = 'ready';
    } catch (err) {
      statusStore.loading = false;
      if (err instanceof ApiError) {
        // Backend reachable but returned error — show specific message
        errorMessage = err.message;
      } else {
        errorMessage = err instanceof Error ? err.message : 'Extension failed to initialize';
      }
      appStatus = 'error';
    }
  });
</script>

{#if appStatus === 'loading'}
  <div class="autom9-loading">
    <p>Loading autom9…</p>
  </div>
{:else if appStatus === 'error'}
  <div class="autom9-error">
    <p><strong>autom9 failed to load</strong></p>
    <p>{errorMessage}</p>
  </div>
{:else}
  <div class="autom9-shell">
    <StatusBar />
    <!-- Chat panel and data panel added in Epic 3 stories -->
  </div>
{/if}

<style>
  .autom9-loading,
  .autom9-error,
  .autom9-shell {
    font-family: sans-serif;
    min-height: 100vh;
  }
  .autom9-loading {
    padding: 1rem;
  }
  .autom9-error {
    color: #c00;
    padding: 1rem;
  }
</style>

